package com.menter.treatmentvault.data

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

@Entity(indices=[Index(value=["name"], unique=true)])
data class SupplyEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val name:String, val stages:String="", val purpose:String="", val necessity:String="按需购买", val purchaseStatus:String="待购", val quantity:Int?=null, val price:Double?=null, val purchaseUrl:String="", val usage:String="", val doctorConfirmed:Boolean=false, val notes:String="", val imagePath:String="", val attachmentPath:String="", val updatedAt:Long=System.currentTimeMillis())
@Entity data class ExamEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val name:String, val date:String="", val hospital:String="", val type:String="其他", val summary:String="", val keyData:String="", val doctorExplanation:String="", val notes:String="", val attachmentPath:String="", val updatedAt:Long=System.currentTimeMillis())
@Entity data class TreatmentPlanEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val name:String, val category:String="其他", val hospital:String="", val doctor:String="", val date:String="", val medicines:String="", val dose:String="", val cycle:String="", val sessions:String="", val startDate:String="", val expectedEnd:String="", val explanation:String="", val notes:String="", val updatedAt:Long=System.currentTimeMillis())
@Entity data class TreatmentRecordEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val date:String, val type:String, val hospital:String="", val doctor:String="", val content:String="", val medicines:String="", val sideEffects:String="", val condition:String="", val notes:String="", val updatedAt:Long=System.currentTimeMillis())
@Entity data class SymptomEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val date:String, val temperature:Double?=null, val weight:Double?=null, val appetite:String="", val nausea:String="", val vomiting:String="", val diarrhea:String="", val constipation:String="", val bowelCount:Int?=null, val urinaryFrequency:String="", val dysuria:String="", val pain:String="", val fatigue:String="", val bleeding:String="", val other:String="", val notes:String="", val updatedAt:Long=System.currentTimeMillis())
@Entity data class QuestionEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val question:String, val date:String="", val hospital:String="", val doctor:String="", val answer:String="", val status:String="待问", val followUp:String="", val notes:String="", val updatedAt:Long=System.currentTimeMillis())
@Entity data class ExpenseEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val date:String="", val type:String="其他", val amount:Double, val merchant:String="", val insuranceAmount:Double=0.0, val selfPayAmount:Double=0.0, val reimbursedAmount:Double=0.0, val notes:String="", val receiptPath:String="", val updatedAt:Long=System.currentTimeMillis())
@Entity data class TimelineEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val date:String, val type:String, val title:String, val content:String="", val sourceType:String="", val sourceId:Long?=null, val important:Boolean=false, val updatedAt:Long=System.currentTimeMillis())
@Entity data class ImportHistoryEntity(@PrimaryKey(autoGenerate=true) val id:Long=0, val packageId:String, val fileName:String, val importedAt:Long=System.currentTimeMillis(), val added:Int=0, val updated:Int=0, val failed:Int=0, val summary:String="")
